218	  const frames: { children: Iterator<LosslessJsonValue>; depth: number }[] = [];
219	  let nodes = 0;
220	  const discover = (value: LosslessJsonValue, depth: number): void => {
221	    // Charge each discovered value before scheduling any of its children.
222	    if (++nodes > 100000 || depth > 16) refuse("bounds");
