260	    });
261	    if (!admitted.ok) refuse("syntax");
262	    phase = "contract";
263	    const envelope = administrativeData(admitted.value, ["format", "profile", "configuration"]);
264	    if (
265	      envelope.format !== "bdptest-reference-deployment-1" ||
266	      envelope.profile !== startup.profile
267	    )
268	      refuse("contract");
269	    const fileDigest = createHash("sha256").update(bytes).digest("hex");
270	    const summary = {
271	      format: "bdptest-reference-deployment-1" as const,
272	      canonicalScope: startup.canonicalScope,
273	      listener: startup.listener,
274	      preflightReadLimits: startup.limits,
275	      fileDigest,
276	    };
277	    if (startup.profile === "read-update") {
278	      const configuration = administrativeData(envelope.configuration, [
279	        "directory",
280	        "create",
281	        "credentials",
282	        "policies",
283	        "contracts",
284	        "maximumEndpointMultiplicity",
285	      ]);
286	      const projectedInput = immutable({
287	        scope: startup.canonicalScope,
288	        listener: startup.listener,
289	        ...configuration,
290	      });
291	      const installed = captureInstalledReferenceConfiguration(projectedInput);
292	      const handle: PreparedReadUpdateDeployment = Object.freeze({
293	        ...summary,
294	        profile: "read-update",
295	        artifactIdentity: installed.artifactIdentity,
296	        configurationIdentity: installed.identity,
297	        policyIdentity: installed.policyIdentity,
298	        authenticationIdentity: installed.authenticationIdentity,
299	      });
300	      phase = "internal";
301	      registerReferenceDeployment(handle, { profile: "read-update", projectedInput, installed });
302	      return handle;
303	    }
304	    const configuration = administrativeData(envelope.configuration, [
305	      "directory",
306	      "create",
307	      "credentials",
308	      "artifacts",
309	    ]);
310	    const projectedInput = immutable({ scope: startup.canonicalScope, ...configuration });
311	    const installed = captureInstalledTransactionConfiguration(projectedInput);
312	    const preflight = captureTransactionRuntimeConfiguration(installed);
313	    if (
314	      preflight.contracts === undefined ||
315	      preflight.authorityMode !== "canonical" ||
316	      preflight.configuredScope !== startup.canonicalScope ||
317	      Object.keys(preflight.seams).length !== 0 ||
318	      !preflight.liveStreamsAvailable ||
319	      preflight.settings.changefeedStream.heartbeatMilliseconds >=
320	        preflight.settings.transport.timeout ||
321	      !isDeepStrictEqual(
322	        preflight.readOptions(startup.canonicalScope).advertisedLimits,
