324	      )
325	    )
326	      refuse("contract");
327	    const handle: PreparedTransactionalDeployment = Object.freeze({
328	      ...summary,
329	      profile: "transactional",
330	      artifactIdentity: preflight.contracts.identity,
331	    });
332	    phase = "internal";
333	    registerReferenceDeployment(handle, {
334	      profile: "transactional",
335	      projectedInput,
336	      installed,
337	      preflight,
338	    });
339	    return handle;
340	  } catch (error) {
341	    if (error instanceof ReferenceDeploymentError) throw error;
342	    // Neither causes nor parser/filesystem/compiler details cross this local boundary.
343	    throw new ReferenceDeploymentError(phase);
344	  }
345	}
